#!/usr/bin/env python3
"""Convert `fixgen fixtures` output to a MoonBit whitebox-test data file.

Usage: fixtures_to_mbt.py <fixtures.txt> <out.mbt>
"""
import sys
from collections import OrderedDict

groups = OrderedDict()
for line in open(sys.argv[1]):
    f = line.split()
    if not f:
        continue
    groups.setdefault(f[0], []).append(' '.join(f[1:]))

out = ['// Generated by testdata/fixgen (`fixgen fixtures` + fixtures_to_mbt.py).',
       '// Do not edit. Each line: input bits [second input bits] expected output bits,',
       '// as produced by pxfm 0.1.30 on x86_64 Linux (default rustc flags, AVX+FMA',
       '// CPU; `*_generic` from a copy whose dispatch never picks the FMA code).',
       '',
       '///|',
       'let fixtures : Array[(String, String)] = [']
for name, lines in groups.items():
    out.append('  (')
    out.append('    "%s",' % name)
    for l in lines:
        out.append('    #|' + l)
    out.append('  ),')
out.append(']')
open(sys.argv[2], 'w').write('\n'.join(out) + '\n')
print({k: len(v) for k, v in groups.items()})
